INSERT INTO vocabularies (topic_id, term, part_of_speech, phonetic, definition, translation, example_sentence, notes, pronunciation_audio_path, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'pedestrian', 'noun', NULL, 'A person who is walking rather than travelling in a vehicle.', 'người đi bộ', 'The new crossing gives pedestrians more time to cross safely.', 'Pedestrian can also describe a path or area.', NULL, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='society-community-public-services' AND NOT EXISTS (SELECT 1 FROM vocabularies existing WHERE existing.topic_id=t.id AND existing.term='pedestrian' AND existing.part_of_speech <=> 'noun');
INSERT INTO vocabularies (topic_id, term, part_of_speech, phonetic, definition, translation, example_sentence, notes, pronunciation_audio_path, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'neighborhood', 'noun', NULL, 'An area of a town where people live.', 'khu phố', 'Our neighborhood holds a small market on the first Sunday.', 'British spelling: neighbourhood.', NULL, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='society-community-public-services' AND NOT EXISTS (SELECT 1 FROM vocabularies existing WHERE existing.topic_id=t.id AND existing.term='neighborhood' AND existing.part_of_speech <=> 'noun');
INSERT INTO grammar_lessons (topic_id, title, slug, objectives, prerequisites, body, examples, common_mistakes, position, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'Past simple and present perfect', 'past-simple-and-present-perfect', 'Choose between a finished past event and an experience or result connected with the present.', 'Basic past forms and common time expressions.', 'Use the past simple for a finished event at a stated or understood past time.
INSERT INTO grammar_lessons (topic_id, title, slug, objectives, prerequisites, body, examples, common_mistakes, position, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'Future plans and predictions', 'future-plans-and-predictions', 'Use will, be going to, and the present continuous for common future meanings.', 'Present forms and the verb be.', 'Use be going to for an intention or a prediction based on present evidence. Use the present continuous for a fixed arrangement. Use will for a decision made now, a promise, or a prediction based on an opinion.', '[{"example":"I am meeting my tutor on Thursday.","explanation":"The present continuous shows a fixed arrangement."},{"example":"Look at those clouds. It is going to rain.","explanation":"The prediction is based on present evidence."}]', 'Use “I will help you” for a decision made at the moment of speaking, not “I am going to help you” unless it was already planned.', 30, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='core-tenses' AND NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE slug='future-plans-and-predictions');
INSERT INTO grammar_lessons (topic_id, title, slug, objectives, prerequisites, body, examples, common_mistakes, position, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'Modals for advice and obligation', 'modals-for-advice-and-obligation', 'Express advice, necessity, and prohibition with should, must, have to, and must not.', 'Basic sentence order and the meaning of need.', 'Use should and should not for advice. Use must or have to for a strong obligation. Use must not for something that is prohibited. The form have to changes for different subjects and tenses, but modal verbs do not take to or an -s ending.', '[{"example":"You should check the address before travelling.","explanation":"Should gives helpful advice."},{"example":"Visitors must not enter this area.","explanation":"Must not expresses prohibition."}]', 'Do not write “She shoulds rest.” Use “She should rest.”', 40, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='core-tenses' AND NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE slug='modals-for-advice-and-obligation');
INSERT INTO grammar_lessons (topic_id, title, slug, objectives, prerequisites, body, examples, common_mistakes, position, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'Comparatives and superlatives', 'comparatives-and-superlatives', 'Compare people, places, and choices clearly in everyday and study contexts.', 'Common adjectives and the verb be.', 'Use a comparative to compare two things, often with than. Use the superlative to compare one thing with a group, usually with the. Short adjectives often take -er and -est; longer adjectives use more and most. Some common forms are irregular.', '[{"example":"The bus is cheaper than a taxi.","explanation":"Cheaper compares two transport choices."},{"example":"This is the most useful part of the guide.","explanation":"Most useful identifies one item in a group."}]', 'Use “more useful,” not “usefuler,” and include than when the second item is named.', 50, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='core-tenses' AND NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE slug='comparatives-and-superlatives');
INSERT INTO passages (topic_id, title, body, word_count, cefr_level, difficulty, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'A quieter start at the community workshop', 'When the Riverside Community Centre opened a free repair workshop, the organisers expected most visitors to arrive on Saturday afternoon. Instead, the busiest time was early Tuesday evening. People came directly from work with lamps, bags, and small kitchen machines. A volunteer called Linh showed visitors how to describe a problem before choosing a solution. The centre did not promise to repair every item. It first checked whether a safe repair was possible and explained the likely cost of parts. This approach reduced waste and helped visitors decide whether to repair, reuse, or replace something. After three months, the organisers added a booking list because the short sessions were regularly full.', 111, 'B1', 1, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='society-community-public-services' AND NOT EXISTS (SELECT 1 FROM passages WHERE title='A quieter start at the community workshop');
INSERT INTO passages (topic_id, title, body, word_count, cefr_level, difficulty, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'A simple plan for healthier evenings', 'Thanh wanted to sleep better, but he did not want a complicated health programme. He began by changing the last hour of his evening. He prepared the next day before dinner, placed his phone on a shelf, and walked around the block after eating. The first week felt difficult because he was used to checking messages in bed. After two weeks, he noticed that he fell asleep more quickly and felt less tired in the morning. He still used his phone when necessary, but he stopped treating every message as urgent. His doctor had suggested that small, regular changes were more useful than a perfect plan that lasted only a few days. Thanh now keeps the routine on busy evenings as well.', 122, 'B1', 1, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='health-and-lifestyle' AND NOT EXISTS (SELECT 1 FROM passages WHERE title='A simple plan for healthier evenings');
INSERT INTO passages (topic_id, title, body, word_count, cefr_level, difficulty, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'Repair before replacement', 'A student group at Westbridge College started a monthly technology desk. Members bring phones and laptops that are slow, damaged, or difficult to use. The desk does not sell equipment and does not keep personal files. Instead, volunteers explain simple checks, such as clearing unused files, updating software, and testing a charger. If a problem needs a professional repair, they say so clearly. The group also talks about privacy. Visitors are asked to back up important material before a device is examined, and no volunteer asks for a password. The project has helped students save money, but its organisers say the main benefit is confidence. People are more willing to solve a small problem when they understand what caused it.', 120, 'B1', 2, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='technology-communication' AND NOT EXISTS (SELECT 1 FROM passages WHERE title='Repair before replacement');
INSERT INTO passages (topic_id, title, body, word_count, cefr_level, difficulty, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'A bus route shaped by its passengers', 'The number 18 bus used to pass the market every hour, but it did not stop near the public library. Older passengers had to cross a busy road and walk several minutes. The transport office invited residents to describe their usual journeys and suggest a safer stop. Some people requested a later evening service, while others preferred more frequent buses in the morning. After reviewing the feedback, the office moved one stop and added a morning bus on weekdays. The change was small, but it helped library staff, market workers, and students. The office plans to collect more comments before changing the evening timetable because a new service must be useful enough to justify its cost.', 116, 'B1', 2, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='travel-tourism-transport' AND NOT EXISTS (SELECT 1 FROM passages WHERE title='A bus route shaped by its passengers');
