INSERT INTO writing_prompts (topic_id, task_type, title, instructions, minimum_words, recommended_minutes, guidance, checklist, model_answer, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'task_1', 'Ask a community centre about a course', 'Write an email of at least 120 words to a community centre. Ask about an evening course, explain why you want to join, and ask what you should bring.', 120, 20, 'Use a clear subject and polite questions. Include a reason for joining and a practical question about the course.', '["I answered every part of the task.","My ideas follow a clear order.","I used useful B1 vocabulary and grammar.","I checked spelling, punctuation, and word count."]', NULL, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='society-community-public-services' AND NOT EXISTS (SELECT 1 FROM writing_prompts WHERE title='Ask a community centre about a course');
INSERT INTO writing_prompts (topic_id, task_type, title, instructions, minimum_words, recommended_minutes, guidance, checklist, model_answer, source_type, source_reference, license_name, license_url, source_notes, status, created_at, updated_at) SELECT t.id, 'task_1', 'Explain a change to a travel plan', 'Write an email of at least 120 words to a friend. Explain a change to a planned journey, give a reason, and suggest a new arrangement.', 120, 20, 'Make the change clear, show how it affects the reader, and end with a specific suggestion.', '["I answered every part of the task.","My ideas follow a clear order.","I used useful B1 vocabulary and grammar.","I checked spelling, punctuation, and word count."]', NULL, 'original', NULL, NULL, NULL, 'Original Sprint 9 batch 1; editorial, answer, and provenance review completed 2026-09-12.', 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM topics t WHERE t.slug='travel-tourism-transport' AND NOT EXISTS (SELECT 1 FROM writing_prompts WHERE title='Explain a change to a travel plan');
